import math
from sys import stdin

def max_gcd_after_move():
    n = int(stdin.readline().strip())
    numbers = list(map(int, stdin.readline().strip().split()))

    current_gcd = math.gcd(numbers[0], numbers[1])
    for i in range(2, n):
        current_gcd = math.gcd(current_gcd, numbers[i])

    max_possible_gcd = 1
    for num in numbers:
        if num % 2 == 0:
            max_possible_gcd = max(max_possible_gcd, 2 * (current_gcd // 2))
        else:
            max_possible_gcd = max(max_possible_gcd, 1)

    return max_possible_gcd

