import math
from sys import stdin

def max_gcd_after_move(N, A):
    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)

    if current_gcd == 1:
        return 1

    target = current_gcd * 2
    if target > 10**9:
        return current_gcd

    for i in range(len(A)):
        if A[i] != current_gcd:
            if A[i] % current_gcd == 0 and (A[i] // current_gcd) % 2 == 0:
                return target

    return current_gcd

